const request = $json;
const validId = (value) => typeof value === 'string' && /^[A-Za-z0-9_-]{1,128}$/.test(value);
const request_id = validId(request.request_id) ? request.request_id : null;
const response = { request_id, context: [], timestamp: new Date().toISOString() };

if (!request_id || !validId(request.user_id) || !validId(request.conversation_id)
    || !['read', 'append', 'delete'].includes(request.operation)) {
  return { json: { ...response, status: 'blocked', error: { code: 'INVALID_CONTEXT_REQUEST' } } };
}

return {
  json: {
    ...response,
    status: 'unavailable',
    error: { code: 'CONTEXT_STORAGE_UNCONFIGURED' },
  },
};
